<script module lang="ts">
/**
 * The conversation screen, with a thread above a composer (`design/archetypes/conversation-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/conversation-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import { devWarning, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/archetypes/conversation-page.module.css'
import Button from '../controls/Button.svelte'
import Drawer from '../overlays/Drawer.svelte'
import PageHeader from '../structure/PageHeader.svelte'
import SplitPane from '../layout/SplitPane.svelte'

export interface ConversationPageProps {
  /**
   * Vocabulary controls with at most one primary, joined by the aside's toggle below the
   * breakpoint.
   */
  actions?: Snippet
  /**
   * An ArtifactPane, beside the thread at wide widths and in a Drawer below the breakpoint.
   */
  aside?: Snippet
  /**
   * The aside's name, used for the separator, the drawer's title and the toggle's label.
   */
  asideLabel?: string
  /**
   * A PromptInput.
   */
  composer: Snippet
  description?: string
  /**
   * A ChatThread.
   */
  thread: Snippet
  title: string
}
</script>

<script lang="ts">
let { actions, aside, asideLabel, composer, description, thread, title }: ConversationPageProps =
  $props()
const joined = joinSlot(undefined, () => ({}))
const slots = {
  get actions() {
    return actions
  },
  get aside() {
    return aside
  },
  get composer() {
    return composer
  },
  get thread() {
    return thread
  },
}
let narrow = $state(false)
let asideOpen = $state(false)
let root = $state<HTMLElement | null>(null)
const measure = $derived(() => {
  if (root === null) return
  const rem = Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16
  const below = root.getBoundingClientRect().width < 48 * rem
  narrow = below
  if (!below) asideOpen = false
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    measure()
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [root]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
watchEffect(effect1)
onDestroy(() => release1?.())
const effect2 = () => {
  devWarning(
    Boolean(slots.aside) && asideLabel === undefined,
    'ConversationPage: an `aside` needs an `asideLabel`, which names the split’s separator, the drawer and its toggle.',
  )
}
watchEffect(effect2)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    class={styles.page}
    data-aside={slots.aside ? (narrow ? 'drawer' : 'split') : undefined}
    data-member="conversation-page"
    >{#snippet actionsOfPageHeader1()
      }{@render actions?.()
      }{#if slots.aside && narrow
        }<Button
          variant="outline"
          tone="neutral"
          size="sm"
          icon="artifact"
          label={asideLabel ?? ''}
          onClick={() => { asideOpen = true }}
      />{/if
    }{/snippet
    }<PageHeader
      {title}
      {description}
      actions={slots.actions || (slots.aside && narrow) ? actionsOfPageHeader1 : undefined}
    /><div class={styles.body}
      >{#if slots.aside && !narrow
        }{#snippet startOfSplitPane2()
          }<div class={styles.conversation}
            ><div class={styles.thread}>{@render thread?.()}</div
            ><div class={styles.composer}>{@render composer?.()}</div
          ></div
        >{/snippet
        }{#snippet endOfSplitPane3()}<div class={styles.aside}>{@render aside?.()}</div>{/snippet
        }<SplitPane
          label={asideLabel ?? ''}
          defaultRatio={0.58}
          startMin={320}
          endMin={280}
          start={startOfSplitPane2}
          end={endOfSplitPane3}
      />{:else
        }<div class={styles.conversation}
          ><div class={styles.thread}>{@render thread?.()}</div
          ><div class={styles.composer}>{@render composer?.()}</div
        ></div
      >{/if
    }</div
    >{#if slots.aside && narrow
      }<Drawer
        side="end"
        size="lg"
        title={asideLabel ?? ''}
        open={asideOpen}
        onOpenChange={(event) => { asideOpen = event }}
        ><div class={styles.drawerAside}>{@render aside?.()}</div
      ></Drawer
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
